CREATE SET TABLE MDP01_META.META_FOREIGN_KEY ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      fk_id INTEGER NOT NULL,      fk_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      child_table_id INTEGER NOT NULL,      child_column_id INTEGER NOT NULL,      parent_table_id INTEGER NOT NULL,      parent_column_id INTEGER NOT NULL,      delete_rule VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC,      update_rule VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC,      is_enforced CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'Y',      comment_string VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      business_relationship VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC,      create_timestamp TIMESTAMP(6),      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( fk_id )UNIQUE INDEX ( child_table_id ,child_column_id ,parent_table_id );